function setCookie(res,v){const h=new Headers(res.headers);h.append("set-cookie",v);return new Response(res.body,{status:res.status,headers:h})}
function withCsrf(res,c){return c?.setCookie?setCookie(res,c.setCookie):res}
function denied(ctx){return html(appPage({title:"Access denied",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content:`<div class="panel"><div class="panel-body"><h2>Permission required</h2><p class="muted">Your account cannot access this page.</p></div></div>`}),403)}
function needAuth(ctx){return ctx.user?null:redirect("/login?msg=Please+sign+in&type=error")}
function needPerm(ctx,p){return needAuth(ctx)||(can(ctx.user,p)?null:denied(ctx))}
function csrfFail(path="/"){return redirect(`${path}?msg=Security+check+failed.+Refresh+and+try+again&type=error`)}
async function context(request,env){
  await ensureSchema(env.DB);
  let user=await loadSession(env.DB,request);
  if(user)user=await hydratePermissions(env.DB,user);
  return{request,env,db:env.DB,user,settings:user?await getSettings(env.DB):{},url:new URL(request.url)};
}
async function selectOptions(db){const [b,g]=await Promise.all([db.prepare("SELECT id,name FROM batches WHERE status='ACTIVE' ORDER BY name").all(),db.prepare("SELECT id,name,batch_id FROM groups_tbl WHERE status='ACTIVE' ORDER BY name").all()]);return{batches:b.results||[],groups:g.results||[]}}
function options(rows,current,key="name"){return rows.map(r=>`<option value="${r.id}" ${selected(current,r.id)}>${esc(r[key])}</option>`).join("")}
function operationError(scope,error){const id=crypto.randomUUID();console.error(scope,id,error?.stack||error);return id}
const AUTO_CODE_META=Object.freeze({students:{table:"students",column:"student_code",prefix:"STU"},batches:{table:"batches",column:"code",prefix:"BAT"},subjects:{table:"subjects",column:"code",prefix:"SUB"},terms:{table:"academic_terms",column:"code",prefix:"TRM"},offerings:{table:"course_offerings",column:"code",prefix:"OFF"}});
function formatAutoCode(prefix,id){return `${prefix}-${String(Number(id)||0).padStart(6,"0")}`}
async function generateAutoCode(db,key,id){
  const meta=AUTO_CODE_META[key];if(!meta||!Number(id))throw new Error(`Unsupported automatic code target: ${key}`);
  const base=formatAutoCode(meta.prefix,id);
  const exists=await db.prepare(`SELECT id FROM ${meta.table} WHERE lower(${meta.column})=lower(?) AND id<>? LIMIT 1`).bind(base,id).first();
  if(!exists)return base;
  for(let i=0;i<6;i++){const suffix=crypto.randomUUID().replaceAll("-","").slice(0,4).toUpperCase(),candidate=`${base}-${suffix}`;const row=await db.prepare(`SELECT id FROM ${meta.table} WHERE lower(${meta.column})=lower(?) AND id<>? LIMIT 1`).bind(candidate,id).first();if(!row)return candidate}
  return `${base}-${crypto.randomUUID().replaceAll("-","").slice(0,8).toUpperCase()}`;
}
function validDateFilter(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||"")&&!Number.isNaN(Date.parse(`${value}T00:00:00.000Z`))}
async function studentRelationErrors(db,{batchId,groupId}){const errors=[];let batch=null,group=null;if(batchId)batch=await db.prepare("SELECT id FROM batches WHERE id=?").bind(batchId).first();if(batchId&&!batch)errors.push("Selected batch does not exist.");if(groupId)group=await db.prepare("SELECT id,batch_id FROM groups_tbl WHERE id=?").bind(groupId).first();if(groupId&&!group)errors.push("Selected group does not exist.");if(group&&batchId&&group.batch_id&&Number(group.batch_id)!==Number(batchId))errors.push("Selected group does not belong to the selected batch.");return errors}

function humanDate(value){return value?esc(String(value).slice(0,10)):"—"}
function offeringName(row){const subject=row.subject_name||row.subject_code||"Subject";const term=row.term_name||"Term";const cohort=row.group_name||row.batch_name||"All students";return `${subject} · ${term} · ${cohort}`}
async function offeringRelationErrors(db,value){
  const errors=[];
  const [subject,term,lecturer,batch,group]=await Promise.all([
    value.subjectId?db.prepare("SELECT id,lecturer_id,status FROM subjects WHERE id=?").bind(value.subjectId).first():null,
    value.termId?db.prepare("SELECT id,status FROM academic_terms WHERE id=?").bind(value.termId).first():null,
    value.lecturerId?db.prepare("SELECT id,status FROM lecturers WHERE id=?").bind(value.lecturerId).first():null,
    value.batchId?db.prepare("SELECT id,status FROM batches WHERE id=?").bind(value.batchId).first():null,
    value.groupId?db.prepare("SELECT id,batch_id,status FROM groups_tbl WHERE id=?").bind(value.groupId).first():null
  ]);
  if(value.subjectId&&!subject)errors.push("Selected subject does not exist.");
  if(value.termId&&!term)errors.push("Selected term / semester does not exist.");
  if(value.lecturerId&&!lecturer)errors.push("Selected lecturer does not exist.");
  if(value.batchId&&!batch)errors.push("Selected batch does not exist.");
  if(value.groupId&&!group)errors.push("Selected group does not exist.");
  if(group&&value.batchId&&group.batch_id&&Number(group.batch_id)!==Number(value.batchId))errors.push("Selected group does not belong to the selected batch.");
  if(value.status==="ACTIVE"){
    if(subject&&subject.status!=="ACTIVE")errors.push("An active course offering requires an active subject.");
    if(term&&term.status!=="ACTIVE")errors.push("An active course offering requires an active term / semester.");
    if(lecturer&&lecturer.status!=="ACTIVE")errors.push("An active course offering cannot use an inactive lecturer.");
    if(batch&&batch.status!=="ACTIVE")errors.push("An active course offering cannot use an inactive batch.");
    if(group&&group.status!=="ACTIVE")errors.push("An active course offering cannot use an inactive group.");
  }
  return {errors,group,subject,term,lecturer,batch};
}

async function studentPlacementConflicts(db,studentId,{batchId,groupId}){
  const rows=(await db.prepare(`SELECT e.id,o.id offering_id,s.name subject_name,t.name term_name,o.batch_id,o.group_id
    FROM enrollments e JOIN course_offerings o ON o.id=e.offering_id JOIN subjects s ON s.id=o.subject_id JOIN academic_terms t ON t.id=o.term_id
    WHERE e.student_id=? AND e.status='ACTIVE' AND o.status='ACTIVE'
      AND ((o.group_id IS NOT NULL AND COALESCE(?,0)<>o.group_id) OR (o.batch_id IS NOT NULL AND COALESCE(?,0)<>o.batch_id))
    ORDER BY e.id DESC LIMIT 10`).bind(studentId,groupId||0,batchId||0).all()).results||[];
  return rows;
}

async function offeringCohortConflicts(db,offeringId,{batchId,groupId}){
  const rows=(await db.prepare(`SELECT e.id,s.id student_id,s.student_code,s.full_name
    FROM enrollments e JOIN students s ON s.id=e.student_id
    WHERE e.offering_id=? AND e.status='ACTIVE'
      AND ((? IS NOT NULL AND COALESCE(s.group_id,0)<>?) OR (? IS NOT NULL AND COALESCE(s.batch_id,0)<>?))
    ORDER BY s.full_name LIMIT 10`).bind(offeringId,groupId,groupId,batchId,batchId).all()).results||[];
  return rows;
}

