async function dependencyCounts(db,items,id){
  const out=[];
  for(const item of items){const row=await db.prepare(item.sql).bind(id).first(),count=Number(row?.n||0);if(count)out.push({label:item.label,count})}
  return out;
}
function dependencyMessage(prefix,items){return `${prefix}: ${items.map(item=>`${item.count} ${item.label}`).join(", ")}.`}
