async function academicActivateError(db,key,row){
  if(key==="groups"&&row.batch_id){const parent=await db.prepare("SELECT status FROM batches WHERE id=?").bind(row.batch_id).first();if(parent&&parent.status!=="ACTIVE")return "Activate the parent Batch first."}
  if(key==="subjects"&&row.lecturer_id){const parent=await db.prepare("SELECT status FROM lecturers WHERE id=?").bind(row.lecturer_id).first();if(parent&&parent.status!=="ACTIVE")return "Activate the default Lecturer first or remove that relationship."}
  return "";
}
function stateActionForms(key,row,csrfToken){
  const closable=key==="terms"||key==="offerings",deactivateLabel=closable?"Close":"Deactivate",activateLabel=closable?"Reopen":"Activate";
  if(row.status==="ACTIVE")return `<form method="post" action="/${key}/${row.id}/status" data-confirm="${deactivateLabel} this record? Related active records may block the action.">${csrfField(csrfToken)}<input type="hidden" name="status" value="INACTIVE"><button class="btn soft small" type="submit">${deactivateLabel}</button></form>`;
  return `<form method="post" action="/${key}/${row.id}/status">${csrfField(csrfToken)}<input type="hidden" name="status" value="ACTIVE"><button class="btn soft small" type="submit">${activateLabel}</button></form><form method="post" action="/${key}/${row.id}/delete" data-confirm="Permanently delete this inactive record? This only succeeds when no related data exists.">${csrfField(csrfToken)}<button class="btn danger small" type="submit">Delete</button></form>`;
}
async function enrollmentEligibility(db,studentId,offeringId){
  const [student,offering]=await Promise.all([
    db.prepare("SELECT id,student_code,full_name,batch_id,group_id,status FROM students WHERE id=?").bind(studentId).first(),
    db.prepare("SELECT id,batch_id,group_id,status FROM course_offerings WHERE id=?").bind(offeringId).first()
  ]);
  if(!student)return {ok:false,message:"Student not found."};
  if(!offering)return {ok:false,message:"Course offering not found."};
  if(student.status!=="ACTIVE")return {ok:false,message:"Only active students can be enrolled."};
  if(offering.status!=="ACTIVE")return {ok:false,message:"Only active course offerings accept new enrollments."};
  if(offering.group_id&&Number(student.group_id)!==Number(offering.group_id))return {ok:false,message:"Student is not assigned to the offering group."};
  if(offering.batch_id&&Number(student.batch_id)!==Number(offering.batch_id))return {ok:false,message:"Student is not assigned to the offering batch."};
  return {ok:true,student,offering};
}

function methodNotAllowed(ctx,methods){const content=`<div class="panel"><div class="panel-body"><h2>405</h2><p class="muted">This page does not accept the ${esc(ctx.request.method)} method.</p></div></div>`;const headers={allow:methods.join(", ")};return ctx.user?html(appPage({title:"Method Not Allowed",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content}),405,headers):html(authPage({title:"Method Not Allowed",subtitle:"Use one of the supported actions for this page.",content:`<a class="btn soft" href="/">Return Home</a>`,version:APP_VERSION}),405,headers)}

