router.add("GET","/setup",async ctx=>{const c=await ctx.db.prepare("SELECT COUNT(*) n FROM users").first();if(Number(c?.n||0))return redirect("/login");const csrf=csrfFor(ctx.request);const warn=ctx.env.AUTH_PEPPER?"":`<div class="notice error"><strong>Recommended:</strong> add the Worker secret AUTH_PEPPER before creating the Owner for stronger password protection.</div>`;const content=`${notice(ctx.url)}${warn}<form method="post" action="/setup" class="grid two">${csrfField(csrf.token)}<label><span>Full Name *</span><input name="full_name" maxlength="120" autocomplete="name" required></label><label><span>Phone</span><input name="phone" maxlength="40" autocomplete="tel"></label><label class="span2"><span>Email Address *</span><input type="email" name="email" maxlength="254" autocomplete="email" required></label><label><span>Password *</span><input type="password" name="password" minlength="8" maxlength="128" autocomplete="new-password" required></label><label><span>Confirm Password *</span><input type="password" name="confirm_password" minlength="8" maxlength="128" autocomplete="new-password" required></label><p class="muted small span2">8–128 characters with uppercase, lowercase and a number.</p><button class="btn primary span2" type="submit">Create Owner Account</button></form>`;return withCsrf(html(authPage({title:"First System Setup",subtitle:"Create the first Owner account. No default credentials are included.",content,version:APP_VERSION})),csrf)});
router.add("POST","/setup",async ctx=>{const existing=await ctx.db.prepare("SELECT COUNT(*) n FROM users").first();if(Number(existing?.n||0))return redirect("/login");const b=await readForm(ctx.request);if(!checkCsrf(ctx.request,b))return csrfFail("/setup");const full=clean(b.full_name,120),email=normalizeEmail(b.email),phone=clean(b.phone,40),password=String(b.password||""),confirm=String(b.confirm_password||"");const errors=[];if(!full)errors.push("Full name is required.");if(!validEmail(email))errors.push("Enter a valid email.");errors.push(...validatePassword(password));if(password!==confirm)errors.push("Passwords do not match.");if(errors.length)return redirect(`/setup?msg=${encodeURIComponent(errors.join(" "))}&type=error`);const hash=await hashPassword(password,ctx.env.AUTH_PEPPER||""),ts=nowIso();const r=await ctx.db.prepare("INSERT INTO users(full_name,email,phone,password_hash,role,status,created_at,updated_at) SELECT ?,?,?,?,'OWNER','ACTIVE',?,? WHERE NOT EXISTS(SELECT 1 FROM users)").bind(full,email,phone,hash,ts,ts).run();if(!Number(r.meta?.changes||0))return redirect("/login?msg=Owner+already+exists");const u=await ctx.db.prepare("SELECT id FROM users WHERE email=?").bind(email).first();await audit(ctx.db,u?.id,"OWNER_CREATED","user",u?.id,"First system owner");return redirect("/login?msg=Owner+created+successfully.+Sign+in+now")});

router.add("GET","/login",async ctx=>{if(ctx.user)return redirect("/dashboard");const c=await ctx.db.prepare("SELECT COUNT(*) n FROM users").first();if(!Number(c?.n||0))return redirect("/setup");const csrf=csrfFor(ctx.request);const content=`${notice(ctx.url)}<form method="post" action="/login" class="grid">${csrfField(csrf.token)}<label><span>Email</span><input type="email" name="email" autocomplete="email" required></label><label><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label><label class="check"><input type="checkbox" name="remember" value="1"><span>Remember me for 30 days</span></label><button class="btn primary" type="submit">Sign In</button><a class="small muted" href="/forgot">Forgot password?</a></form>`;return withCsrf(html(authPage({title:"Sign In",subtitle:"Use your system account to continue.",content,version:APP_VERSION})),csrf)});
router.add("POST","/login",async ctx=>{
  const b=await readForm(ctx.request);if(!checkCsrf(ctx.request,b))return csrfFail("/login");
  const email=normalizeEmail(b.email),password=String(b.password||""),pepper=ctx.env.AUTH_PEPPER||"",fp=await fingerprint(ctx.request,pepper);
  const since=new Date(Date.now()-15*60*1000).toISOString();
  const recent=await ctx.db.batch([
    ctx.db.prepare("SELECT COUNT(*) n FROM login_attempts WHERE email=? AND success=0 AND created_at>?").bind(email,since),
    ctx.db.prepare("SELECT COUNT(*) n FROM login_attempts WHERE fingerprint=? AND success=0 AND created_at>?").bind(fp,since)
  ]);
  if(Number(recent[0]?.results?.[0]?.n||0)>=8||Number(recent[1]?.results?.[0]?.n||0)>=30)return redirect("/login?msg=Too+many+failed+attempts.+Try+again+later&type=error");
  const u=validEmail(email)?await ctx.db.prepare("SELECT * FROM users WHERE email=? AND status='ACTIVE'").bind(email).first():null;
  const ok=Boolean(u)&&await verifyPassword(password,u.password_hash,pepper);
  await ctx.db.prepare("INSERT INTO login_attempts(email,fingerprint,success,created_at) VALUES(?,?,?,?)").bind(email,fp,ok?1:0,nowIso()).run();
  if(!ok)return redirect("/login?msg=Invalid+email+or+password&type=error");
  if(needsPasswordRehash(u.password_hash,pepper))await ctx.db.prepare("UPDATE users SET password_hash=?,updated_at=? WHERE id=?").bind(await hashPassword(password,pepper),nowIso(),u.id).run();
  await ctx.db.prepare("DELETE FROM login_attempts WHERE success=0 AND (email=? OR fingerprint=?)").bind(email,fp).run();
  const s=await createSession(ctx.db,u.id,ctx.request,String(b.remember||"")==="1");
  await ctx.db.prepare("UPDATE users SET last_login_at=? WHERE id=?").bind(nowIso(),u.id).run();
  await audit(ctx.db,u.id,"LOGIN","session","","");
  try{await pruneOperationalData(ctx.db)}catch(error){operationError("pruneOperationalData",error)}
  return setCookie(redirect("/dashboard"),makeCookie("sid",s.token,{maxAge:s.maxAge}));
});
router.add("GET","/logout",async ctx=>{const deny=needAuth(ctx);if(deny)return deny;const csrf=csrfFor(ctx.request),content=`<div class="panel"><div class="panel-body"><h2>Sign out?</h2><p class="muted">This will end the current session on this device.</p><form method="post" action="/logout">${csrfField(csrf.token)}<div class="actions"><button class="btn danger" type="submit">Sign Out</button><a class="btn soft" href="/dashboard">Cancel</a></div></form></div></div>`;return withCsrf(html(appPage({title:"Sign Out",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content})),csrf)});
