function studentForm(s,o,csrf){
  const today=new Date().toISOString().slice(0,10);
  const groupOptions=o.groups.map(r=>`<option value="${r.id}" data-batch-id="${r.batch_id||""}" ${selected(s.group_id,r.id)}>${esc(r.name)}</option>`).join("");
  return `<form method="post" class="grid two" data-student-form>${csrfField(csrf)}<label><span>Student Code <span class="code-auto-badge">AUTO</span></span><input name="student_code" maxlength="60" autocomplete="off" value="${esc(s.student_code||"")}" placeholder="Automatic: STU-000001"><small class="muted">Leave blank and the system generates a unique code automatically.</small></label><label><span>Full Name *</span><input name="full_name" maxlength="150" autocomplete="name" required value="${esc(s.full_name||"")}"></label><label><span>Email</span><input type="email" name="email" maxlength="254" autocomplete="email" value="${esc(s.email||"")}"></label><label><span>Phone</span><input name="phone" maxlength="40" autocomplete="tel" inputmode="tel" value="${esc(s.phone||"")}"></label><label><span>Gender</span><select name="gender"><option value="">—</option><option ${selected(s.gender,"Male")}>Male</option><option ${selected(s.gender,"Female")}>Female</option></select></label><label><span>Birth Date</span><input type="date" name="birth_date" max="${today}" value="${esc(s.birth_date||"")}"></label><label><span>Batch</span><select name="batch_id" data-student-batch><option value="">—</option>${options(o.batches,s.batch_id)}</select></label><label><span>Group</span><select name="group_id" data-student-group><option value="">—</option>${groupOptions}</select><small class="muted">Groups are filtered by the selected batch.</small></label><label><span>Status</span><select name="status"><option ${selected(s.status||"ACTIVE","ACTIVE")}>ACTIVE</option><option ${selected(s.status,"INACTIVE")}>INACTIVE</option></select></label><label class="span2"><span>Notes</span><textarea name="notes" maxlength="3000">${esc(s.notes||"")}</textarea></label><div class="span2 actions"><button class="btn primary" type="submit">Save Student</button><a class="btn soft" href="/students">Cancel</a></div></form>`;
}
