function roleOptions(actor,current="VIEWER"){return USER_ROLES.filter(role=>canAssignRole(actor,role)||role===current).map(role=>`<option value="${role}" ${selected(current,role)}>${role.replaceAll("_"," ")}</option>`).join("")}
