  const sets=await permissionSetsForRows(ctx.db,rows),hasNext=page*USERS_PAGE_SIZE<total;
  const body=rows.map(u=>{const pset=sets.get(Number(u.id))||new Set(),manage=canManageTarget(ctx.user,u);return `<tr><td><a class="table-link user-name-link" href="/users/${u.id}"><strong>${esc(u.full_name)}</strong></a><div class="small muted">${esc(u.email)}</div></td><td>${roleBadge(u.role)}</td><td>${badge(u.status)}</td><td><span class="permission-count">${pset.size}/${PERMISSIONS.length}</span></td><td>${u.last_activity_at?formatDateTime(u.last_activity_at):"Never"}</td><td>${Number(u.active_sessions||0)}</td><td>${Number(u.reset_requests||0)?`<span class="badge warn">${Number(u.reset_requests)} pending</span>`:"—"}</td><td><div class="row-actions"><a class="btn soft small" href="/users/${u.id}">View</a>${manage?`<a class="btn soft small" href="/users/${u.id}/edit">Manage</a>`:""}</div></td></tr>`}).join("");
