router.add("GET","/settings",async ctx=>{
  const deny=needPerm(ctx,"settings.view");if(deny)return deny;const csrf=csrfFor(ctx.request),editable=can(ctx.user,"settings.manage"),schema=await ctx.db.prepare("SELECT value FROM app_meta WHERE key='schema_version'").first(),schemaVersion=Number(schema?.value||0),pepper=Boolean(ctx.env.AUTH_PEPPER);
  const content=`<div class="grid two"><section class="panel"><div class="panel-head"><div><h2>Organization</h2><p class="panel-kicker">Shared identity shown throughout the administration interface.</p></div></div><div class="panel-body"><form method="post" class="grid two">${csrfField(csrf.token)}<label><span>Organization Name *</span><input name="organization_name" maxlength="150" required value="${esc(ctx.settings.organization_name||"")}" ${editable?"":"disabled"}></label><label><span>Support Email</span><input type="email" name="support_email" maxlength="254" value="${esc(ctx.settings.support_email||"")}" ${editable?"":"disabled"}></label>${editable?`<div class="span2"><button class="btn primary" type="submit">Save Settings</button></div>`:""}</form></div></section><section class="panel"><div class="panel-head"><div><h2>Production Diagnostics</h2><p class="panel-kicker">Quick checks for the deployed Worker and database state.</p></div></div><div class="panel-body"><div class="detail-grid"><div><span>Application</span><strong>${esc(APP_SLUG)}</strong></div><div><span>Version</span><strong>${esc(APP_VERSION)}</strong></div><div><span>D1 Binding</span><strong>${ctx.env.DB?`<span class="badge ok">Connected</span>`:`<span class="badge warn">Missing</span>`}</strong></div><div><span>Database Schema</span><strong>${schemaVersion>=CURRENT_SCHEMA_VERSION?`<span class="badge ok">v${schemaVersion}</span>`:`<span class="badge warn">v${schemaVersion} / needs v${CURRENT_SCHEMA_VERSION}</span>`}</strong></div><div><span>AUTH_PEPPER</span><strong>${pepper?`<span class="badge ok">Configured</span>`:`<span class="badge warn">Missing</span>`}</strong></div><div><span>Health Check</span><strong><a class="text-link" href="/health" target="_blank" rel="noopener">Open /health</a></strong></div></div>${!pepper?`<div class="notice warning" role="alert">Configure AUTH_PEPPER in Cloudflare Secrets before creating or changing production passwords.</div>`:""}${schemaVersion<CURRENT_SCHEMA_VERSION?`<div class="notice warning" role="alert">Database migration is required before this release is production-ready.</div>`:""}</div></section></div>`;
  return withCsrf(html(appPage({title:"Settings",user:ctx.user,settings:ctx.settings,active:"settings",url:ctx.url,content})),csrf)
});
router.add("POST","/settings",async ctx=>{
  const deny=needPerm(ctx,"settings.manage");if(deny)return deny;const b=await readForm(ctx.request);if(!checkCsrf(ctx.request,b))return csrfFail("/settings");
  const parsed=settingsInput(b);if(parsed.errors.length)return redirect(`/settings?msg=${encodeURIComponent(parsed.errors.join(" "))}&type=error`);
  const ts=nowIso(),{organizationName,supportEmail}=parsed.value;
  await ctx.db.batch([
    ctx.db.prepare("INSERT INTO settings(key,value,updated_at) VALUES('organization_name',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at").bind(organizationName,ts),
    ctx.db.prepare("INSERT INTO settings(key,value,updated_at) VALUES('support_email',?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at").bind(supportEmail,ts)
  ]);
  invalidateSettingsCache(ctx.db);await audit(ctx.db,ctx.user.id,"SETTINGS_UPDATE","settings","","");return redirect("/settings?msg=Settings+saved");
});

export default{
  async fetch(request,env){
    try{
      const url=new URL(request.url),publicPaths=["/assets/app.css","/assets/app.js","/version","/health"];
      if(publicPaths.includes(url.pathname)){
        const res=await router.handle(request,{request,env,url});if(res)return res;
        const methods=router.methodsFor(url.pathname);if(methods.length)return methodNotAllowed({request,env,url,user:null,settings:{}},methods);
        return text("Not found",404);
      }
      if(!env.DB)return html(authPage({title:"Database Not Connected",subtitle:"This project needs a Cloudflare D1 binding named DB.",content:`<div class="notice error" role="alert">Configure the existing Cloudflare D1 database as binding DB, then redeploy. The production predeploy check prevents accidental deployment to an unpinned database.</div>`,version:APP_VERSION}),500);
      const ctx=await context(request,env),res=await router.handle(request,ctx);if(res)return res;
      const methods=router.methodsFor(url.pathname);if(methods.length)return methodNotAllowed(ctx,methods);
      if(ctx.user)return html(appPage({title:"Not Found",user:ctx.user,settings:ctx.settings,active:"",url:ctx.url,content:`<div class="panel"><div class="panel-body"><h2>404</h2><p class="muted">The requested page does not exist.</p></div></div>`}),404);
      return html(authPage({title:"Not Found",content:`<a class="btn soft" href="/">Return Home</a>`,version:APP_VERSION}),404);
    }catch(error){
      const id=crypto.randomUUID();console.error("Unhandled error",id,error?.stack||error);
      return html(authPage({title:"Something went wrong",subtitle:`Request ID: ${id}`,content:`<div class="notice error" role="alert">The request could not be completed. Check Cloudflare Logs using the Request ID above.</div><a class="btn soft" href="/">Return Home</a>`,version:APP_VERSION}),500);
    }
  }
};
